package com.dailyhelp.controller;
import com.dailyhelp.dto.AuthDtos.*; import com.dailyhelp.service.AuthService; import jakarta.servlet.http.*; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.authentication.*; import org.springframework.security.core.Authentication; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.security.web.context.HttpSessionSecurityContextRepository; import org.springframework.security.web.context.SecurityContextRepository; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/auth") public class AuthController {private final AuthService auth;private final AuthenticationManager manager;private final SecurityContextRepository contextRepo=new HttpSessionSecurityContextRepository();public AuthController(AuthService auth,AuthenticationManager manager){this.auth=auth;this.manager=manager;}
 @PostMapping("/register") ResponseEntity<UserResponse> register(@Valid @RequestBody RegisterRequest r){return ResponseEntity.status(201).body(auth.register(r));}
 @PostMapping("/login") ResponseEntity<UserResponse> login(@Valid @RequestBody LoginRequest r,HttpServletRequest request,HttpServletResponse response){Authentication a=manager.authenticate(new UsernamePasswordAuthenticationToken(r.email().trim().toLowerCase(),r.password()));var context=SecurityContextHolder.createEmptyContext();context.setAuthentication(a);SecurityContextHolder.setContext(context);contextRepo.saveContext(context,request,response);return ResponseEntity.ok(auth.current(a.getName()));}
 @GetMapping("/me") UserResponse me(Authentication a){return auth.current(a.getName());}
}